PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "scheduler_product" ("product_id" varchar(32) NOT NULL PRIMARY KEY, "sku_code" varchar(32) NOT NULL UNIQUE, "name" varchar(120) NOT NULL, "category" varchar(32) NOT NULL, "unit" varchar(12) NOT NULL, "lifecycle_state" varchar(12) NOT NULL, "created_at" datetime NOT NULL);
CREATE INDEX "scheduler_p_categor_4d35d1_idx" ON "scheduler_product" ("category", "lifecycle_state");
CREATE TABLE "scheduler_routing" ("routing_id" varchar(48) NOT NULL PRIMARY KEY, "version" smallint unsigned NOT NULL CHECK ("version" >= 0), "effective_from" date NOT NULL, "effective_to" date NULL, "lifecycle_state" varchar(12) NOT NULL, "created_at" datetime NOT NULL, "product_id" varchar(32) NOT NULL REFERENCES "scheduler_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_product_routing_version" UNIQUE ("product_id", "version"), CONSTRAINT "routing_effective_dates_valid" CHECK (("effective_to" IS NULL OR "effective_to" >= ("effective_from"))));
CREATE INDEX "scheduler_routing_product_id_2e91b990" ON "scheduler_routing" ("product_id");
CREATE TABLE "scheduler_machine" ("machine_id" varchar(16) NOT NULL PRIMARY KEY, "name" varchar(80) NOT NULL, "machine_type" varchar(24) NOT NULL, "capacity_units_per_hour" decimal NOT NULL, "location" varchar(60) NOT NULL, "lifecycle_state" varchar(12) NOT NULL, "available_from" date NOT NULL, "available_to" date NULL, CONSTRAINT "machine_capacity_positive" CHECK ("capacity_units_per_hour" > '0'), CONSTRAINT "machine_availability_dates_valid" CHECK (("available_to" IS NULL OR "available_to" >= ("available_from"))));
CREATE TABLE "scheduler_machinecalendar" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "weekday" smallint unsigned NOT NULL CHECK ("weekday" >= 0), "shift_start" time NOT NULL, "shift_end" time NOT NULL, "capacity_minutes" smallint unsigned NOT NULL CHECK ("capacity_minutes" >= 0), "effective_from" date NOT NULL, "effective_to" date NULL, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_machine_calendar_shift" UNIQUE ("machine_id", "weekday", "shift_start", "effective_from"), CONSTRAINT "machine_calendar_weekday_range" CHECK (("weekday" >= 0 AND "weekday" <= 6)), CONSTRAINT "machine_calendar_shift_valid" CHECK ("shift_end" > ("shift_start")), CONSTRAINT "machine_calendar_capacity_positive" CHECK ("capacity_minutes" > 0), CONSTRAINT "machine_calendar_dates_valid" CHECK (("effective_to" IS NULL OR "effective_to" >= ("effective_from"))));
CREATE INDEX "scheduler_machinecalendar_machine_id_ed8cc33f" ON "scheduler_machinecalendar" ("machine_id");
CREATE TABLE "scheduler_machinedowntime" ("downtime_id" varchar(32) NOT NULL PRIMARY KEY, "start_at" datetime NOT NULL, "end_at" datetime NOT NULL, "reason" varchar(120) NOT NULL, "issue_type" varchar(24) NOT NULL, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "downtime_end_after_start" CHECK ("end_at" > ("start_at")));
CREATE INDEX "scheduler_machinedowntime_machine_id_eb93f517" ON "scheduler_machinedowntime" ("machine_id");
CREATE TABLE "scheduler_material" ("material_id" varchar(24) NOT NULL PRIMARY KEY, "name" varchar(120) NOT NULL, "category" varchar(32) NOT NULL, "unit" varchar(12) NOT NULL, "lifecycle_state" varchar(12) NOT NULL);
CREATE TABLE "scheduler_inventorylot" ("lot_id" varchar(32) NOT NULL PRIMARY KEY, "lot_number" varchar(40) NOT NULL, "quantity" decimal NOT NULL, "available_from" date NOT NULL, "expiry_date" date NULL, "quality_status" varchar(16) NOT NULL, "material_id" varchar(24) NOT NULL REFERENCES "scheduler_material" ("material_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_material_lot_number" UNIQUE ("material_id", "lot_number"), CONSTRAINT "inventory_lot_quantity_positive" CHECK ("quantity" > '0'), CONSTRAINT "inventory_lot_dates_valid" CHECK (("expiry_date" IS NULL OR "expiry_date" >= ("available_from"))));
CREATE INDEX "scheduler_inventorylot_material_id_b3a52ee2" ON "scheduler_inventorylot" ("material_id");
CREATE TABLE "scheduler_tooling" ("tooling_id" varchar(16) NOT NULL PRIMARY KEY, "name" varchar(80) NOT NULL, "capacity" smallint unsigned NOT NULL CHECK ("capacity" >= 0), "lifecycle_state" varchar(12) NOT NULL, CONSTRAINT "tooling_capacity_positive" CHECK ("capacity" > 0));
CREATE TABLE "scheduler_machinetooling" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, "tooling_id" varchar(16) NOT NULL REFERENCES "scheduler_tooling" ("tooling_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_machine_tooling" UNIQUE ("machine_id", "tooling_id"));
CREATE INDEX "scheduler_machinetooling_machine_id_1559a8b0" ON "scheduler_machinetooling" ("machine_id");
CREATE INDEX "scheduler_machinetooling_tooling_id_d8113f7c" ON "scheduler_machinetooling" ("tooling_id");
CREATE TABLE "scheduler_routingstep" ("step_id" varchar(48) NOT NULL PRIMARY KEY, "sequence_no" smallint unsigned NOT NULL CHECK ("sequence_no" >= 0), "name" varchar(80) NOT NULL, "base_minutes_per_unit" smallint unsigned NOT NULL CHECK ("base_minutes_per_unit" >= 0), "required_workers" smallint unsigned NOT NULL CHECK ("required_workers" >= 0), "machine_type_required" varchar(24) NOT NULL, "setup_family" varchar(32) NOT NULL, "routing_id" varchar(48) NOT NULL REFERENCES "scheduler_routing" ("routing_id") DEFERRABLE INITIALLY DEFERRED, "tooling_id" varchar(16) NULL REFERENCES "scheduler_tooling" ("tooling_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_routing_step_sequence" UNIQUE ("routing_id", "sequence_no"), CONSTRAINT "routing_step_duration_positive" CHECK ("base_minutes_per_unit" > 0), CONSTRAINT "routing_step_workers_positive" CHECK ("required_workers" >= 1));
CREATE INDEX "scheduler_routingstep_routing_id_ce1fb922" ON "scheduler_routingstep" ("routing_id");
CREATE INDEX "scheduler_routingstep_tooling_id_2906a195" ON "scheduler_routingstep" ("tooling_id");
CREATE TABLE "scheduler_routingstepmachine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, "routing_step_id" varchar(48) NOT NULL REFERENCES "scheduler_routingstep" ("step_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_step_eligible_machine" UNIQUE ("routing_step_id", "machine_id"));
CREATE INDEX "scheduler_routingstepmachine_machine_id_241bb3eb" ON "scheduler_routingstepmachine" ("machine_id");
CREATE INDEX "scheduler_routingstepmachine_routing_step_id_7e4b7c9c" ON "scheduler_routingstepmachine" ("routing_step_id");
CREATE TABLE "scheduler_productmaterial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity_per_unit" decimal NOT NULL, "material_id" varchar(24) NOT NULL REFERENCES "scheduler_material" ("material_id") DEFERRABLE INITIALLY DEFERRED, "product_id" varchar(32) NOT NULL REFERENCES "scheduler_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_product_material_bom" UNIQUE ("product_id", "material_id"), CONSTRAINT "bom_quantity_positive" CHECK ("quantity_per_unit" > '0'));
CREATE INDEX "scheduler_productmaterial_material_id_22c37ee7" ON "scheduler_productmaterial" ("material_id");
CREATE INDEX "scheduler_productmaterial_product_id_f65f2c8a" ON "scheduler_productmaterial" ("product_id");
CREATE TABLE "scheduler_laborshift" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "weekday" smallint unsigned NOT NULL CHECK ("weekday" >= 0), "shift_start" time NOT NULL, "shift_end" time NOT NULL, "workers_available" smallint unsigned NOT NULL CHECK ("workers_available" >= 0), "effective_from" date NOT NULL, "effective_to" date NULL, CONSTRAINT "uq_labor_shift" UNIQUE ("weekday", "shift_start", "effective_from"), CONSTRAINT "labor_weekday_range" CHECK (("weekday" >= 0 AND "weekday" <= 6)), CONSTRAINT "labor_workers_positive" CHECK ("workers_available" > 0), CONSTRAINT "labor_shift_time_valid" CHECK ("shift_end" > ("shift_start")), CONSTRAINT "labor_shift_dates_valid" CHECK (("effective_to" IS NULL OR "effective_to" >= ("effective_from"))));
CREATE TABLE "scheduler_changeovermatrix" ("changeover_id" varchar(40) NOT NULL PRIMARY KEY, "from_setup" varchar(32) NOT NULL, "to_setup" varchar(32) NOT NULL, "changeover_minutes" smallint unsigned NOT NULL CHECK ("changeover_minutes" >= 0), "effective_from" date NOT NULL, "effective_to" date NULL, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_machine_changeover_pair" UNIQUE ("machine_id", "from_setup", "to_setup", "effective_from"), CONSTRAINT "changeover_effective_dates_valid" CHECK (("effective_to" IS NULL OR "effective_to" >= ("effective_from"))));
CREATE INDEX "scheduler_changeovermatrix_machine_id_a7359af6" ON "scheduler_changeovermatrix" ("machine_id");
CREATE TABLE "scheduler_productionorder" ("order_id" varchar(32) NOT NULL PRIMARY KEY, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "order_date" date NOT NULL, "due_date" date NOT NULL, "priority" smallint unsigned NOT NULL CHECK ("priority" >= 0), "status" varchar(12) NOT NULL, "created_at" datetime NOT NULL, "product_id" varchar(32) NOT NULL REFERENCES "scheduler_product" ("product_id") DEFERRABLE INITIALLY DEFERRED, "routing_id" varchar(48) NOT NULL REFERENCES "scheduler_routing" ("routing_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "production_order_quantity_positive" CHECK ("quantity" > 0), CONSTRAINT "production_order_due_after_order" CHECK ("due_date" >= ("order_date")), CONSTRAINT "production_order_priority_range" CHECK (("priority" >= 1 AND "priority" <= 5)));
CREATE INDEX "scheduler_productionorder_product_id_568ff3b3" ON "scheduler_productionorder" ("product_id");
CREATE INDEX "scheduler_productionorder_routing_id_e0813c7c" ON "scheduler_productionorder" ("routing_id");
CREATE INDEX "scheduler_p_status_85af51_idx" ON "scheduler_productionorder" ("status", "priority", "due_date");
CREATE TABLE "scheduler_operation" ("operation_id" varchar(64) NOT NULL PRIMARY KEY, "sequence_no" smallint unsigned NOT NULL CHECK ("sequence_no" >= 0), "duration_minutes" integer unsigned NOT NULL CHECK ("duration_minutes" >= 0), "required_workers" smallint unsigned NOT NULL CHECK ("required_workers" >= 0), "status" varchar(12) NOT NULL, "order_id" varchar(32) NOT NULL REFERENCES "scheduler_productionorder" ("order_id") DEFERRABLE INITIALLY DEFERRED, "routing_step_id" varchar(48) NOT NULL REFERENCES "scheduler_routingstep" ("step_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_order_operation_sequence" UNIQUE ("order_id", "sequence_no"), CONSTRAINT "operation_duration_positive" CHECK ("duration_minutes" > 0), CONSTRAINT "operation_workers_positive" CHECK ("required_workers" >= 1));
CREATE INDEX "scheduler_operation_order_id_637eec43" ON "scheduler_operation" ("order_id");
CREATE INDEX "scheduler_operation_routing_step_id_738a2f5b" ON "scheduler_operation" ("routing_step_id");
CREATE INDEX "scheduler_o_status_884bc1_idx" ON "scheduler_operation" ("status", "sequence_no");
CREATE TABLE "scheduler_operationeligiblemachine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, "operation_id" varchar(64) NOT NULL REFERENCES "scheduler_operation" ("operation_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_operation_eligible_machine" UNIQUE ("operation_id", "machine_id"));
