CREATE INDEX "scheduler_operationeligiblemachine_operation_id_6552fe41" ON "scheduler_operationeligiblemachine" ("operation_id");
CREATE TABLE "scheduler_schedulingrun" ("run_id" varchar(40) NOT NULL PRIMARY KEY, "strategy" varchar(80) NOT NULL, "seed" bigint unsigned NOT NULL CHECK ("seed" >= 0), "status" varchar(12) NOT NULL, "planning_start" datetime NOT NULL, "created_at" datetime NOT NULL, "completed_at" datetime NULL, "metrics" text NOT NULL CHECK ((JSON_VALID("metrics") OR "metrics" IS NULL)));
CREATE TABLE "scheduler_operationschedule" ("schedule_id" varchar(32) NOT NULL PRIMARY KEY, "start_at" datetime NOT NULL, "end_at" datetime NOT NULL, "setup_minutes" smallint unsigned NOT NULL CHECK ("setup_minutes" >= 0), "processing_minutes" integer unsigned NOT NULL CHECK ("processing_minutes" >= 0), "decision_reason" varchar(240) NOT NULL, "created_at" datetime NOT NULL, "machine_id" varchar(16) NOT NULL REFERENCES "scheduler_machine" ("machine_id") DEFERRABLE INITIALLY DEFERRED, "operation_id" varchar(64) NOT NULL REFERENCES "scheduler_operation" ("operation_id") DEFERRABLE INITIALLY DEFERRED, "run_id" varchar(40) NOT NULL REFERENCES "scheduler_schedulingrun" ("run_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_run_operation_schedule" UNIQUE ("run_id", "operation_id"), CONSTRAINT "schedule_end_after_start" CHECK ("end_at" > ("start_at")), CONSTRAINT "schedule_processing_positive" CHECK ("processing_minutes" > 0));
