CREATE TABLE "scheduler_materialreservation" ("reservation_id" varchar(40) NOT NULL PRIMARY KEY, "quantity" decimal NOT NULL, "reserved_at" datetime NOT NULL, "lot_id" varchar(32) NOT NULL REFERENCES "scheduler_inventorylot" ("lot_id") DEFERRABLE INITIALLY DEFERRED, "material_id" varchar(24) NOT NULL REFERENCES "scheduler_material" ("material_id") DEFERRABLE INITIALLY DEFERRED, "order_id" varchar(32) NOT NULL REFERENCES "scheduler_productionorder" ("order_id") DEFERRABLE INITIALLY DEFERRED, "run_id" varchar(40) NOT NULL REFERENCES "scheduler_schedulingrun" ("run_id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_run_order_material_lot" UNIQUE ("run_id", "order_id", "material_id", "lot_id"), CONSTRAINT "reservation_quantity_positive" CHECK ("quantity" > '0'));
CREATE INDEX "scheduler_materialreservation_lot_id_213c311d" ON "scheduler_materialreservation" ("lot_id");
CREATE INDEX "scheduler_materialreservation_material_id_3197fa86" ON "scheduler_materialreservation" ("material_id");
CREATE INDEX "scheduler_materialreservation_order_id_d44b3f11" ON "scheduler_materialreservation" ("order_id");
CREATE INDEX "scheduler_materialreservation_run_id_b2d14eba" ON "scheduler_materialreservation" ("run_id");
CREATE TABLE "scheduler_scheduleexception" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "issue_type" varchar(32) NOT NULL, "severity" varchar(12) NOT NULL, "message" varchar(300) NOT NULL, "details" text NOT NULL CHECK ((JSON_VALID("details") OR "details" IS NULL)), "detected_at" datetime NOT NULL, "operation_id" varchar(64) NULL REFERENCES "scheduler_operation" ("operation_id") DEFERRABLE INITIALLY DEFERRED, "run_id" varchar(40) NOT NULL REFERENCES "scheduler_schedulingrun" ("run_id") DEFERRABLE INITIALLY DEFERRED);
