CREATE TABLE "scheduler_auditevent" ("event_id" varchar(48) NOT NULL PRIMARY KEY, "entity_type" varchar(40) NOT NULL, "entity_id" varchar(64) NOT NULL, "event_type" varchar(60) NOT NULL, "actor" varchar(80) NOT NULL, "payload" text NOT NULL CHECK ((JSON_VALID("payload") OR "payload" IS NULL)), "occurred_at" datetime NOT NULL);
CREATE INDEX "scheduler_a_entity__4c4e29_idx" ON "scheduler_auditevent" ("entity_type", "entity_id");
